const resultPath = '.opencode-review-result.json';
let parsed = null;
if (fs.existsSync(resultPath)) {
  // Guard against a stale committed/half-written result: only trust files updated during THIS run.
  const resultMtime = Math.floor(fs.statSync(resultPath).mtimeMs / 1000);
  if (resultMtime + 30 < startTs) {
    core.warning(`${resultPath} pre-dates this run; ignoring stale file.`);
  } else {
    try {
      parsed = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
    } catch (err) {
      core.warning(`Failed to parse ${resultPath}: ${err.message}`);
    }
  }
  try { fs.unlinkSync(resultPath); } catch (_) {}
}
